import { createHash } from 'node:crypto';

/** Examples golden case identity (inspection / PHPStan pack). */
export type ExamplesGoldenMeta = {
  /**
   * Suite stem from the filename (`function`, `docblock`, …).
   * Used for namespace hashing only — not written into begin JSON.
   */
  readonly stem: string;
  readonly input: string;
  readonly requireClass?: readonly string[];
};

export type ExamplesGoldenCase = {
  readonly meta: ExamplesGoldenMeta;
  readonly namespaceId: string;
  readonly expected: string;
  readonly startLine: number;
  readonly endLine: number;
};

const BEGIN_PREFIX = '// @gtc-golden-begin ';
const END_MARKER = '// @gtc-golden-end';
const CODE_GENERATED =
  '// Code generated by yarn update_fixtures:generator; DO NOT EDIT.';
const NAMESPACE_RE = /^namespace Golden\\(e[a-f0-9]{12}) \{$/u;
const BEGIN_RE = /^\/\/ @gtc-golden-begin (.+)$/u;

/** Stable key; never includes the expected PHP body. */
export function canonicalExamplesCaseKey(meta: ExamplesGoldenMeta): string {
  return JSON.stringify({
    kind: 'examples',
    stem: meta.stem,
    input: meta.input,
    requireClass: meta.requireClass ?? [],
  });
}

/**
 * PHP-safe namespace leaf: `e` + first 12 hex chars (distinct from checker `h…`).
 */
export function namespaceIdForExamplesCase(meta: ExamplesGoldenMeta): string {
  const hex = createHash('sha256')
    .update(canonicalExamplesCaseKey(meta), 'utf8')
    .digest('hex')
    .slice(0, 12);
  return `e${hex}`;
}

function metaToBeginJson(meta: ExamplesGoldenMeta): string {
  const obj: {
    input: string;
    requireClass?: readonly string[];
  } = { input: meta.input };
  if (meta.requireClass !== undefined && meta.requireClass.length > 0) {
    obj.requireClass = meta.requireClass;
  }
  return JSON.stringify(obj);
}

function parseMetaJson(raw: string, stem: string): ExamplesGoldenMeta {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new Error(`invalid examples @gtc-golden-begin JSON: ${String(err)}`, {
      cause: err,
    });
  }
  if (typeof parsed !== 'object' || parsed === null) {
    throw new Error('invalid examples begin JSON: expected object');
  }
  if (!('input' in parsed) || typeof parsed.input !== 'string') {
    throw new Error('invalid examples begin JSON: missing input');
  }
  const meta: {
    stem: string;
    input: string;
    requireClass?: readonly string[];
  } = { stem, input: parsed.input };
  if ('requireClass' in parsed && Array.isArray(parsed.requireClass)) {
    const names = parsed.requireClass.filter(
      (x): x is string => typeof x === 'string',
    );
    if (names.length > 0) {
      meta.requireClass = names;
    }
  }
  return meta;
}

function formatCaseBlock(meta: ExamplesGoldenMeta, expected: string): string {
  const id = namespaceIdForExamplesCase(meta);
  const body = expected.endsWith('\n') ? expected.slice(0, -1) : expected;
  return `${BEGIN_PREFIX}${metaToBeginJson(meta)}\nnamespace Golden\\${id} {\n${body}\n}\n${END_MARKER}`;
}

/** Encode `<stem>.examples.golden.php`. */
export function formatExamplesGoldenPhp(
  stem: string,
  cases: readonly {
    readonly meta: ExamplesGoldenMeta;
    readonly expected: string;
  }[],
): string {
  const seen = new Map<string, string>();
  const blocks: string[] = [];
  for (const item of cases) {
    const id = namespaceIdForExamplesCase(item.meta);
    const key = canonicalExamplesCaseKey(item.meta);
    const prev = seen.get(id);
    if (prev !== undefined) {
      if (prev === key) {
        continue;
      }
      throw new Error(`namespace collision Golden\\${id}: ${prev} vs ${key}`);
    }
    seen.set(id, key);
    blocks.push(formatCaseBlock(item.meta, item.expected));
  }

  const header = [
    '<?php',
    '',
    CODE_GENERATED,
    `// Generator examples fixtures for ${stem}.IN.`,
    '',
    'declare(strict_types = 1);',
  ].join('\n');

  if (blocks.length === 0) {
    return `${header}\n`;
  }
  return `${header}\n\n${blocks.join('\n\n')}\n`;
}

function readCaseBody(
  lines: readonly string[],
  bodyStart: number,
  startLine: number,
): { readonly expected: string; readonly endLine: number; readonly nextIndex: number } {
  let i = bodyStart;
  const bodyLines: string[] = [];
  while (i < lines.length) {
    const cur = lines[i];
    if (cur === undefined) {
      throw new Error('never reached');
    }
    if (cur === '}' && lines[i + 1] === END_MARKER) {
      break;
    }
    bodyLines.push(cur);
    i += 1;
  }
  if (i >= lines.length || lines[i] !== '}') {
    throw new Error(`missing namespace close for examples case at line ${startLine}`);
  }
  i += 1;
  if (lines[i] !== END_MARKER) {
    throw new Error(`missing ${END_MARKER} for examples case at line ${startLine}`);
  }
  return {
    expected: bodyLines.length === 0 ? '' : `${bodyLines.join('\n')}\n`,
    endLine: i + 1,
    nextIndex: i + 1,
  };
}

/**
 * Parse `<stem>.examples.golden.php`.
 * `stem` comes from the filename (not from begin JSON).
 */
export function parseExamplesGoldenPhp(
  source: string,
  stem: string,
): ExamplesGoldenCase[] {
  const lines = source.split('\n');
  const cases: ExamplesGoldenCase[] = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (line === undefined) {
      throw new Error('never reached');
    }
    if (!line.startsWith(BEGIN_PREFIX)) {
      i += 1;
      continue;
    }
    const begin = BEGIN_RE.exec(line);
    if (begin === null || begin[1] === undefined) {
      throw new Error(`invalid begin at line ${i + 1}`);
    }
    const startLine = i + 1;
    const meta = parseMetaJson(begin[1], stem);
    const expectedId = namespaceIdForExamplesCase(meta);
    const nsLine = lines[i + 1];
    if (nsLine === undefined) {
      throw new Error(`missing namespace after begin at line ${startLine}`);
    }
    const nsMatch = NAMESPACE_RE.exec(nsLine);
    if (nsMatch === null || nsMatch[1] !== expectedId) {
      throw new Error(
        `expected namespace Golden\\${expectedId} at line ${startLine + 1}`,
      );
    }
    const body = readCaseBody(lines, i + 2, startLine);
    cases.push({
      meta,
      namespaceId: expectedId,
      expected: body.expected,
      startLine,
      endLine: body.endLine,
    });
    i = body.nextIndex;
  }
  return cases;
}
